/**
 * Database migration script that reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

// Directory containing migration files
const MIGRATIONS_DIR = './migrations';

// Read migration files from the directory
fs.readdir(MIGRATIONS_DIR, (err, files) => {
    if (err) {
        console.error('Error reading migrations directory:', err);
        process.exit(1);
    }

    // Filter out non-SQL files and sort them
    const migrationFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort();

    // Log each migration file in order
    console.log('Migration files to apply (in order):');
    migrationFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);
    });

    console.log(`Total migrations to apply: ${migrationFiles.length}`);
});

