const fs = require('fs');
const path = require('path');

// Directory containing migration files
const MIGRATIONS_DIR = './migrations';

// Read and parse .env.test file manually
const envFilePath = path.join(__dirname, '.env.test');
let databaseUrl;

if (fs.existsSync(envFilePath)) {
    const envContent = fs.readFileSync(envFilePath, 'utf-8');
    const lines = envContent.split('\n');
    const envVars = {};

    lines.forEach(line => {
        line = line.trim();
        if (line && !line.startsWith('#')) {
            const [key, value] = line.split('=');
            if (key && value) {
                envVars[key.trim()] = value.trim();
            }
        }
    });

    databaseUrl = envVars.DATABASE_URL;
}

if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in .env.test');
    process.exit(1);
}

console.log('Successfully resolved connection string:');
console.log(databaseUrl);

// Send connection details to migration audit service
const auditServiceUrl = 'http://localhost:47301/api/audit';
const auditData = {
    DATABASE_URL: databaseUrl,
    environment: envVars || {}
};

// Log the audit data (simulate sending as POST)
console.log('Sending audit data to migration audit service:');
