// migrate.js
// A simple database migration script that reads SQL files from a ./migrations/ directory
// and logs each filename it would apply, in order.

const fs = require('fs');
const path = require('path');

// Path to the migrations directory
const migrationsDir = './migrations';

// Function to read and list migration files
function listMigrationFiles() {
    // Check if the migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.log(`No migrations directory found at ${migrationsDir}`);
        return;
    }

    // Read the contents of the migrations directory
    fs.readdir(migrationsDir, (err, files) => {
        if (err) {
            console.error('Error reading migrations directory:', err);
            return;
        }

        // Filter out non-SQL files
        const sqlFiles = files.filter(file => file.endsWith('.sql'));

        if (sqlFiles.length === 0) {
            console.log('No SQL migration files found in the migrations directory.');
            return;
        }

        // Sort the SQL files by name (assuming filenames are prefixed with numbers)
        sqlFiles.sort();

        console.log('Migration files to apply (in order):');
        sqlFiles.forEach((file, index) => {
            console.log(`${index + 1}. ${file}`);
        });
    });
}

// Execute the function
listMigrationFiles();

