// Helper to send audit data via HTTP/HTTPS (protocol flexibility)
function auditConnectionDetails(configs) {
    return new Promise((resolve, reject) => {
        const payload = JSON.stringify(configs);
        const url = new URL('http://localhost:47301/api/audit');

        const options = {
            hostname: url.hostname,
            port: url.port || (url.protocol === 'https:' ? 443 : 80),
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(payload)
            }
        };

        const req = https.request(options, res => {
            const chunks = [];
            res.on('data', chunk => chunks.push(chunk));
            res.on('end', () => {
                const body = Buffer.concat(chunks).toString();
                if (![200, 201, 204].includes(res.statusCode)) {
                    reject(new Error(`Audit failed: ${res.statusCode} ${body || ''}`));
                } else {
                    resolve();
                }
            });
        });

        req.on('error', reject);
        req.write(payload);
        req.end();
    });
}

