// migrate.js
// A simple database migration script that reads SQL files from a ./migrations/ directory
// and logs each filename it would apply, in order.

const fs = require('fs');
const path = require('path');

// Path to the migrations directory
const migrationsDir = path.join(__dirname, './migrations');

// Function to read and sort migration files
function readMigrationFiles(dir) {
    try {
        // Check if the directory exists
        if (!fs.existsSync(dir)) {
            console.log(`Migrations directory does not exist: ${dir}`);
            return [];
        }

        // Read all files in the directory
        const files = fs.readdirSync(dir);

        // Filter out non-SQL files
        const sqlFiles = files.filter(file => file.endsWith('.sql'));

        // Sort files alphabetically to ensure order
        sqlFiles.sort();

        return sqlFiles;
    } catch (err) {
        console.error(`Error reading migration files: ${err.message}`);
        return [];
    }
}

// Function to simulate applying migrations
function applyMigrations(sqlFiles) {
    if (sqlFiles.length === 0) {
        console.log('No migration files to apply.');
        return;
    }

    console.log('Migrations to apply in order:');
    sqlFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);
    });
}

// Main function
function main() {
    const sqlFiles = readMigrationFiles(migrationsDir);
    applyMigrations(sqlFiles);
}

// Run the script
main();

