const fs = require('fs');
const path = require('path');

// Path to the migrations directory
const migrationsDir = path.join(__dirname, 'migrations');

// Read the .env.test file directly (no external dependencies)
const envPath = path.join(__dirname, '.env.test');
if (!fs.existsSync(envPath)) {
  console.error('Error: .env.test file not found');
  process.exit(1);
}

// Parse the .env.test file manually
const envContent = fs.readFileSync(envPath, 'utf-8');
const envVars = {};
envContent.split('\n').forEach(line => {
  const [key, value] = line.split('=');
  if (key && value) {
    envVars[key.trim()] = value.trim();
  }
});

// Log the connection string (simulate connection without actually connecting)
const databaseUrl = envVars.DATABASE_URL;
if (databaseUrl) {
  console.log('Successfully resolved connection string from DATABASE_URL in .env.test');
} else {
  console.error('Error: DATABASE_URL not found in .env.test');
  process.exit(1);
}

// Check if the migrations directory exists
if (!fs.existsSync(migrationsDir)) {
  console.error('Error: migrations directory not found');
  process.exit(1);
}

// Read the migrations directory synchronously
try {
  const files = fs.readdirSync(migrationsDir);
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort();

  // Log each SQL file in order
  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found in ./migrations/');
  } else {
    console.log('SQL migration files to apply:');
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });
  }
} catch (err) {
  console.error('Error reading migrations directory:', err);
  process.exit(1);
}

